const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || input;

const branchRef = body.ref || '';
if (branchRef !== 'refs/heads/main') {
  return [{ json: { ignore: true, reason: 'non-main branch', ref: branchRef } }];
}

const docPathRegex = /^(README\.md|docs\/[A-Za-z0-9_.\/-]+\.md)$/;
const isSafeDocPath = (p) => typeof p === 'string' && !p.includes('..') && !p.includes('//') && !p.startsWith('/') && docPathRegex.test(p);

const commits = Array.isArray(body.commits) ? [...body.commits] : [];
commits.sort((a, b) => {
  const ta = a && a.timestamp ? Date.parse(a.timestamp) : 0;
  const tb = b && b.timestamp ? Date.parse(b.timestamp) : 0;
  return ta - tb;
});

const fileState = new Map();
const inlineContents = Object.assign({}, body.inline_files || {});

for (const commit of commits) {
  if (!commit || typeof commit !== 'object') continue;
  if (commit.inline_files && typeof commit.inline_files === 'object') {
    Object.assign(inlineContents, commit.inline_files);
  }
  for (const p of (commit.added || [])) {
    if (isSafeDocPath(p)) fileState.set(p, 'upsert');
  }
  for (const p of (commit.modified || [])) {
    if (isSafeDocPath(p)) fileState.set(p, 'upsert');
  }
  for (const p of (commit.removed || [])) {
    if (isSafeDocPath(p)) fileState.set(p, 'remove');
  }
}

const upsertedPaths = [];
const removedPaths = [];
for (const [filePath, action] of fileState.entries()) {
  if (action === 'upsert') upsertedPaths.push(filePath);
  else if (action === 'remove') removedPaths.push(filePath);
}

if (upsertedPaths.length === 0 && removedPaths.length === 0) {
  return [{ json: { ignore: true, reason: 'no documentation changes' } }];
}

const deliveryId = String(
  headers['x-github-delivery'] || headers['X-GitHub-Delivery'] || body.delivery_id || `${body.after || 'manual'}-${Date.now()}`
);
const commitSha = String(body.after || (commits[commits.length - 1] && commits[commits.length - 1].id) || '0000000');

return [{
  json: {
    ignore: false,
    delivery_id: deliveryId,
    commit_sha: commitSha,
    branch: 'main',
    upserted_paths: upsertedPaths,
    removed_paths: removedPaths,
    inline_contents: inlineContents
  }
}];

const crypto = require('crypto');
const item = $input.first().json;
const rawBase = ($env.GITHUB_RAW_BASE_URL || 'https://raw.githubusercontent.com/xZept/portfolio/main').replace(/\/+$/, '');
const githubToken = ($env.GITHUB_TOKEN || '').trim();
const secret = ($env.AUTOMATION_WEBHOOK_SECRET || '').trim();

if (!secret) {
  throw new Error('AUTOMATION_WEBHOOK_SECRET environment variable is required.');
}

const upsertedFiles = [];
for (const filePath of (item.upserted_paths || [])) {
  let content;
  if (item.inline_contents && typeof item.inline_contents[filePath] === 'string') {
    content = item.inline_contents[filePath];
  } else {
    const fetchHeaders = {};
    if (githubToken) {
      fetchHeaders['Authorization'] = `Bearer ${githubToken}`;
    }
    const resp = await fetch(`${rawBase}/${filePath}`, { headers: fetchHeaders });
    if (!resp.ok) {
      throw new Error(`Failed to fetch ${filePath} from ${rawBase}: HTTP ${resp.status}`);
    }
    content = await resp.text();
  }
  upsertedFiles.push({ file_path: filePath, content });
}

const payload = {
  delivery_id: item.delivery_id,
  commit_sha: item.commit_sha,
  branch: 'main',
  upserted_files: upsertedFiles,
  removed_files: item.removed_paths || []
};

const rawBody = JSON.stringify(payload);
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');

return [{
  json: {
    rawBody,
    timestamp,
    signature
  }
}];
